Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
//typedef long double ld;

const int maxn=5007;

//const ll INF = 1e18;
const ll INF =  1e9;
const ll mod = 1e9+7;

struct Edge {
    int from,to;
    ll cap, cost, flow;
    Edge(int from, int to, ll cap, ll cost): from(from), to(to), cap(cap), cost(cost), flow(0) {};
};

vector<Edge> edges;
ll d[maxn], phi[maxn];
vector<int> g[maxn];
int par[maxn];

void add_edge(int u, int v, ll cap, ll cost) {
    g[u].push_back(edges.size());
    edges.push_back({u,v,cap,cost});
    g[v].push_back(edges.size());
    edges.push_back({v,u,0,-cost});
}
void ford_bellman(int s, int n) {
    for (int i=0;i<maxn;i++) {
        phi[i] = INF;
    }
    phi[s] = 0;
    for (int i=0;i<n;i++) {
        for (int j=0;j<edges.size();j++) {
            if (edges[j].cap==edges[j].flow) continue;
            int from = edges[j].from;
            int to = edges[j].to;
            ll len = edges[j].cost;
            if (phi[from]==INF) continue;
            phi[to] = min(phi[to], phi[from]+len);
        }
    }
}

void dijkstra(int s) {
    for (int i=0;i<maxn;i++) {
        d[i] = INF;
    }
    d[s] = 0;
    set<pair<ll,int>> q;
    q.insert({0,s});
    while (!q.empty()) {
        int v = q.begin()->second;
        q.erase(q.begin());
        for (int i=0;i<g[v].size();i++) {
            int eid = g[v][i];
            if (edges[eid].cap==edges[eid].flow) continue;
            int to = edges[eid].to;
            ll len = edges[eid].cost + phi[v] - phi[to];
            if (d[v]+len<d[to]) {
                q.erase({d[to],to});
                d[to] = d[v]+len;
                par[to] = eid;
                q.insert({d[to],to});
            }
        }
    }
}

pair<ll,ll> mincost_maxflow(int s, int t) {
    ford_bellman(s, 50);
    dijkstra(s);
    ll flow = 0, cost = 0;
    while (1) {
        if (d[t]==INF) break;
        ll pushed=  INF, sum = 0;
        for (int tmp = t;tmp!=s;) {
//            if (tmp==100) {
//                cout << "xyu";
//            }
            int eid = par[tmp];
            pushed = min(pushed, edges[eid].cap-edges[eid].flow);
            sum+=edges[eid].cost;
            tmp = edges[eid].from;
        }
        flow+=pushed;
        cost+=pushed*sum;
        //cout << "flow: " << flow << ", cost: " << cost << endl <<  t << " ";
        for (int tmp=t;tmp!=s;) {
            int eid = par[tmp];
            edges[eid].flow+=pushed;
            edges[eid^1].flow-=pushed;
            tmp = edges[eid].from;
          //  cout << tmp << " ";
        }
        //cout << endl;

        dijkstra(s);
        for (int i=0;i<maxn;i++) {
            phi[i] = d[i];
        }
    }
    return {cost, flow};
}
void solve() {
    int n,m,k,c,d;
    cin >> n >> m >> k >> c >> d;
    vector<int> cnts(n,0);
    for (int i=0;i<k;i++) {
        int ai;
        cin >> ai;
        ai--;
        cnts[ai]++;
    }
    for (int i=0;i<n;i++) {
        add_edge(5000, i, cnts[i],0);
    }
    for (int it=0;it<m;it++) {
        int u,v;
        cin >> u >> v;
        u--; v--;
        for (int i=0;i<99;i++) {
            ll cost = d;
            for (int j=0;j<50;j++) {
                add_edge(u+i*50, v+(i+1)*50, 1, cost);
                add_edge(v+i*50, u+(i+1)*50, 1, cost);
                cost+=2*d;
            }
        }
    }
    for (int i=0;i<=99;i++) {
        add_edge(0+i*50, 5001, INF, c*i);
    }

    for (int i=0;i<n;i++) {
        for (int j=0;j<99;j++) {
            add_edge(i+j*50, i+(j+1)*50, INF, 0);
        }
    }
    //add_edge(0+99*50, 5001, INF, 0);

    auto p = mincost_maxflow(5000, 5001);
    assert(p.second==k);
    cout << p.first;
}
int main() {
    cin.tie(0);
    cout.tie(0);
    ios_base::sync_with_stdio(false);
    cout << setprecision(20) << fixed;
   // freopen("input.txt","r", stdin);
//    int t;
//    cin >> t;
//    for (int i=0;i<t;i++)
    solve();
    return 0;
}
